import React from 'react';
import Step from './Step/Step';
import { StepperProps } from './StepperTypes';
import StepperContext from './StepperContext';
import { StepData } from './Step/StepTypes';
import './Stepper.scss';
import clsx from 'clsx';
import useWindowSize from '../../hooks/useWindowSize';


const Stepper: React.FC<StepperProps> = ({
  id,
  steps,
  children,    
  errorSteps = [],
  activeStep = 0,
  colour = "primary",
  ...rest
}) => {

  let buttonClassName = "mpa-step-button ";
  switch (colour) {
    case "primary":
      buttonClassName += "mpa-btn-primary";
      break;
    case "secondary":
      buttonClassName += "mpa-btn-secondary";
      break;
    case "tertiary":
      buttonClassName += "mpa-btn-tertiary";
       break;
    default:
      buttonClassName += "mpa-btn-primary";
      break;
  }

  let hideConnectors = false;
  const contextValue = React.useMemo(
    () => ({
      activeStep,      
      hideConnectors,
      buttonClassName,
      errorSteps,
    }),
    [
      activeStep,     
      hideConnectors,
      buttonClassName,
      errorSteps
    ]
  );

  const useStepsProp = steps instanceof Array && steps.length > 0;
  const stepsArray = (useStepsProp
    ? steps
    : React.Children.toArray(children)) as Array<
    | StepData
    | (
        | string
        | number
        | React.ReactElement<any, string | React.JSXElementConstructor<any>>
        | React.ReactNode
        | React.ReactPortal
      )
  >;
  const { isMobile } = useWindowSize();
  const stepsToRender = stepsArray.map((step, index) => {
    if (!useStepsProp && !React.isValidElement(step)) return null;
    const stepProps = {      
      index,
    };

    return (
      <div key={index} id="mpa-StepContainer" className={clsx("mpa-step-container", { "step-container-mobile": isMobile })}>
        {React.isValidElement(step) ? (
          React.cloneElement(step, {
            ...stepProps,
            ...step.props,
          })
        ) : (
          // <Step {...stepProps} {...(typeof step === 'object' ? step : {})} />
          <Step index={index} {...step as StepData} />
        )}
      </div>
    );
  });


  return (
    <StepperContext.Provider value={contextValue}>
      <div
        id="mpa-StepperContainer"
        className={clsx("mpa-stepper-container", { "stepper-container-mobile": isMobile })}
        {...rest}
      >
        {stepsToRender}
      </div>
    </StepperContext.Provider>
  );
};

export default Stepper;
